/** All supplied signed cuts before merge, no candidate-state prefix after refusal/refutation. */
public final class ContextUniversalSignedRoundsRunner {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static Snapshot bind(boolean x,String s)throws Exception{return ContextPrivateWitnessPoolRunner.bind(x,s);}
    static ContextUniversalFrozenBranch.Limits full(){return ContextUniversalFrozenBranchRunner.full();}
    static Result run(Snapshot x,List<Snapshot> a,Packet p,Map<Cut,PrivatePool> pools,int rounds){return ContextUniversalSignedRounds.run(x,a,p,pools,full(),rounds,WORK);}
    static boolean has(Packet p,String pred,boolean positive){return p.items.stream().anyMatch(i->i.atom.predicate.equals(pred)&&i.atom.positive==positive);}
    static Result stable(Result r){require(r.status==Status.STABLE_SIGNED_POOLS&&r.output!=null&&r.output.merged&&r.history.size()==r.completedRounds&&r.refutations.isEmpty(),r.phase+" "+r.reason);audit(r);return r;}
    static void incomplete(Result r,String phase,int completed,String why){require(r.status==Status.INCOMPLETE&&r.output==null&&r.history.isEmpty()&&r.refutations.isEmpty()&&r.completedRounds==completed&&(phase==null||r.phase.equals(phase)),why+": "+r.phase+" "+r.reason);}
    static void refuted(Result r,int round,String why){require(r.status==Status.REFUTED&&r.output==null&&r.history.isEmpty()&&!r.refutations.isEmpty()&&r.completedRounds==round-1,why+": "+r.phase+" "+r.reason);for(Refutation f:r.refutations.values()){require(f.round==round&&(f.xRefuted||f.foreignRefuted)&&!f.proofs.isEmpty(),"actual checked current-barrier refutation");Set<Proof> seen=Collections.newSetFromMap(new IdentityHashMap<Proof,Boolean>());for(Proof p:f.proofs){require(p.clause==null,"only genuine empty proofs in rejection evidence");auditProof(p,seen);}}}
    static void auditProof(Proof p,Set<Proof> seen){if(!seen.add(p))return;if(p.original!=null)require(p.original.parts.contains(p.part)&&p.support.depth==0&&p.support.sources.equals(Collections.singleton(p.original.original.source)),"actual original whole Source0");else if(p.input!=null)require(p.input.proofs.contains(p.inputProof)&&p.support.equals(p.inputProof),"actual historical Item/Support, no reset");else{auditProof(p.unit,seen);auditProof(p.horn,seen);org.kanger.ContextUniversalInputResiduals.Residual expected=ContextUniversalInputResiduals.resolveSignedUnit(p.unit.clause,p.horn.clause,p.pivot,()->{});require(p.clause==null?expected==null:expected!=null&&p.clause.equivalent(expected,()->{}),"signed principal resolvent including empty");Set<Source> sources=new HashSet<>(p.unit.support.sources);sources.addAll(p.horn.support.sources);require(p.support.sources.equals(sources)&&p.support.depth==Math.max(p.unit.support.depth,p.horn.support.depth)+1,"complete Source/depth evidence");}}
    static void audit(Result r){Packet prior=r.input;Map<Cut,PrivatePool> pools=null;for(Round n:r.history){require(n.input==prior&&n.checks.keySet().equals(n.barrier.branches.keySet()),"all exact signed cuts before barrier");for(Map.Entry<Cut,ContextUniversalFrozenConstraints.Result> e:n.checks.entrySet()){ContextUniversalFrozenConstraints.Result c=e.getValue();require(c.closed&&c.signedUnits&&!c.xRefuted&&!c.foreignRefuted&&c.common==n.input&&c.pool==n.privateInput.get(e.getKey()),"every branch checked against same actual common/private input");require(n.barrier.branches.get(e.getKey()).proof==c,"actual checked closure owns transfer");ContextUniversalFrozenBranchRunner.unmarked(n.barrier.branches.get(e.getKey()).output);}if(pools!=null)for(Cut cut:pools.keySet())require(n.privateInput.get(cut)==pools.get(cut),"actual prior rebased private object");require(n.commonChanged==!ContextWitnessResultTransport.sameContents(n.input,n.barrier.packet,WORK),"entire signed common Source/depth pools compared");prior=n.barrier.packet;pools=n.barrier.privatePools;}Round last=r.history.get(r.history.size()-1);require(!last.commonChanged&&!last.privateChanged&&!last.barrier.localChanged&&last.barrier==r.output,"final whole checked round unchanged");Map<Cut,Packet> packets=new LinkedHashMap<>();for(Map.Entry<Cut,ConstraintTransfer> e:r.output.branches.entrySet())packets.put(e.getKey(),e.getValue().output);require(ContextWitnessResultTransport.family(last.input,new ArrayList<>(packets.keySet()),WORK).finish(packets,WORK).status==FamilyStatus.INCOMPLETE,"stable signed pools issue no family STEP");}
    static void originalAndMergedOpposites()throws Exception {
        String rule="!@w left(w,1)&&right(w,1)->p(w,1);",left="!left(1,1);",right="!right(1,1);",np="!~p(1,1);";
        Snapshot x=bind(true,"!anchor(1); "+rule),a=bind(false,left+"!p(1,1);"),b=bind(false,right+np);Packet input=ContextPrivateWitnessPoolRunner.common(x);Set<Source> expected=new HashSet<>(Arrays.asList(ContextPrivateWitnessPoolRunner.source(x,rule),ContextPrivateWitnessPoolRunner.source(a,left),ContextPrivateWitnessPoolRunner.source(b,right),ContextPrivateWitnessPoolRunner.source(b,np)));
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(a,b),Arrays.asList(b,a))){Result r=run(x,order,input,Collections.emptyMap(),8);refuted(r,2,"original example rejects on next immutable barrier in both orders");Refutation f=r.refutations.get(Cut.of(a));require(f!=null&&f.xRefuted&&!f.foreignRefuted,"A detects B's negative left production");require(f.proofs.stream().anyMatch(p->p.support.depth==3&&p.support.sources.equals(expected)),"exact original rule+B right/not-p+A left history at empty3");require(!f.inputIdentity.equals(input.identity),"refutation sees next actual common input, not same-round branch output");}
        incomplete(run(x,Arrays.asList(a,b),input,Collections.emptyMap(),1),"round-limit",1,"round cap hides merged proposal before next qualification");
        ContextUniversalFrozenBranch.Limits depth=new ContextUniversalFrozenBranch.Limits(16,2,16,512,256,WORK,500000,65536);incomplete(ContextUniversalSignedRounds.run(x,Arrays.asList(a,b),input,Collections.emptyMap(),depth,8,WORK),"checks",1,"later empty3 proof cap returns incomplete, not false collision or stable prefix");
        ContextUniversalFrozenBranch.Limits fact=new ContextUniversalFrozenBranch.Limits(16,16,1,512,256,WORK,500000,65536);incomplete(ContextUniversalSignedRounds.run(x,Arrays.asList(a,b),input,Collections.emptyMap(),fact,8,WORK),"transfers",0,"later negative fact2 failure hides earlier transfers");
        require(input.items.size()==1&&!has(input,"left",false),"original common unmodified after every failure/refutation");
        Snapshot sx=bind(true,"!anchor(1); !@w left(w,1)->p(w,1); !@w right(w,1)->~p(w,1);"),sa=bind(false,left),sb=bind(false,right);Packet common=ContextPrivateWitnessPoolRunner.common(sx);Result peers=run(sx,Arrays.asList(sa,sb),common,Collections.emptyMap(),8);refuted(peers,2,"opposite same-round peer products cannot escape as stable output");require(peers.refutations.containsKey(Cut.of(sx))&&peers.refutations.get(Cut.of(sx)).proofs.stream().anyMatch(p->p.support.depth==2&&p.support.sources.size()==4),"mandatory self-X detects merged positive/negative products at empty2");
    }
    static void stableSourcePoolsAndIndependence()throws Exception {
        Snapshot x=bind(true,"!p(1);"),a=bind(false,"!@w p(w)->q(w);"),b=bind(false,"!@w q(w)->p(w);");Packet input=ContextPrivateWitnessPoolRunner.common(x);Result r=stable(run(x,Arrays.asList(a,b),input,Collections.emptyMap(),8));require(r.completedRounds==4,"Source alternatives stabilize4 although atoms stabilize earlier");require(r.history.get(1).input.items.size()==r.history.get(1).barrier.packet.items.size()&&r.history.get(1).commonChanged,"Source-only growth prevents early stop");Result reverse=stable(run(x,Arrays.asList(b,a),input,Collections.emptyMap(),8));require(reverse.completedRounds==r.completedRounds&&ContextWitnessResultTransport.sameContents(r.output.packet,reverse.output.packet,WORK),"both cut orders preserve full signed proof pools");stable(run(x,Arrays.asList(a,b),r.output.packet,Collections.emptyMap(),1));
        incomplete(run(x,Arrays.asList(a,b),input,Collections.emptyMap(),2),"round-limit",2,"atom stability is not full signed-pool stability");
        Snapshot anchor=bind(true,"!anchor(1);"),pa=bind(false,"!p(1);"),pb=bind(false,"!~p(1);");Packet common=ContextPrivateWitnessPoolRunner.common(anchor);Result independent=stable(run(anchor,Arrays.asList(pa,pb),common,Collections.emptyMap(),1));require(!has(independent.output.packet,"p",true)&&!has(independent.output.packet,"p",false),"independent A/B may disagree without an X-dependent production");
        Snapshot symbolic=bind(false,"!@w p(w,1);");Result open=stable(run(anchor,Collections.singletonList(symbolic),common,Collections.emptyMap(),1));require(open.history.get(0).checks.get(Cut.of(symbolic)).proofs.stream().anyMatch(p->p.clause!=null&&!p.clause.variables.isEmpty()),"symbolic units stay visible; stable fixed-unit pools are not complete universal coverage");
        try{r.history.clear();throw new AssertionError();}catch(UnsupportedOperationException expected){++checks;}
    }
    static void privatePools()throws Exception {
        Snapshot x=bind(true,"!anchor(1);"),a=bind(false,"!$w seed(w,1); !@w seed(w,1)->~flag(w,1);"),b=bind(false,"!@w seed(w,1)->seen(w,1);");Packet input=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(input,x,a,WORK);Map<Cut,PrivatePool> pools=Collections.singletonMap(pool.cut,pool);Result r=stable(run(x,Arrays.asList(a,b),input,pools,8));require(r.completedRounds==2&&!r.history.get(0).commonChanged&&r.history.get(0).privateChanged,"private negative growth continues despite unchanged common");PrivatePool after=r.output.privatePools.get(pool.cut);require(has(after.local,"flag",false)&&!has(r.output.packet,"flag",false)&&!has(r.output.packet,"seed",true)&&!has(r.output.packet,"seen",true),"negative raw/private facts stay local and independent B cannot borrow seed");require(after.common==r.output.packet&&!has(pool.local,"flag",false),"private signed continuation rebased only after collection, old pool immutable");stable(run(x,Arrays.asList(b,a),after.common,r.output.privatePools,1));
        incomplete(run(x,Arrays.asList(a,b),input,pools,1),"round-limit",1,"private-only change cannot return common-stable success");incomplete(run(x,Collections.singletonList(a),input,Collections.emptyMap(),8),"checks",0,"missing private original inventory is not partial qualification");incomplete(run(x,Collections.singletonList(a),ContextPrivateWitnessPoolRunner.common(x),pools,8),"preflight",0,"equal common contents cannot replace exact private frame");
        Snapshot owner=bind(true,"!anchor(1); !@w seed(w,1)->~flag(w,1);"),raw=bind(false,"!$w seed(w,1);"),opinion=bind(false,"!@w flag(w,1);");Packet common=ContextPrivateWitnessPoolRunner.common(owner);PrivatePool actual=ContextWitnessResultTransport.privatePool(common,owner,raw,WORK);Result collision=run(owner,Arrays.asList(raw,opinion),common,Collections.singletonMap(actual.cut,actual),8);refuted(collision,2,"shared negative private-witness production qualifies independent opinion next round");require(collision.refutations.get(Cut.of(opinion)).proofs.stream().anyMatch(p->p.support.depth==2&&p.support.sources.size()==3),"actual private binding history survives into foreign universal refutation");
    }
    static void signedRebaseGuards()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@w seed(w,1)->~flag(w,1);"),a=bind(false,"!$w seed(w,1);");Packet common=ContextPrivateWitnessPoolRunner.common(x);PrivatePool pool=ContextWitnessResultTransport.privatePool(common,x,a,WORK);
        ContextUniversalFrozenConstraints.Result c=ContextUniversalFrozenConstraints.closeSigned(ContextUniversalNativeRows.inspect(x,a,64,WORK),common,pool,16,16,512,256,WORK);ConstraintTransfer t=ContextWitnessResultTransport.transferConstraintsPrivate(c,pool,16,WORK);require(t.transferred&&has(t.output,"flag",false),"concrete signed common rebase fixture");
        try{ContextWitnessResultTransport.privatePool(t.output,x,a,WORK);throw new AssertionError();}catch(IllegalStateException expected){++checks;}
        try{ContextWitnessResultTransport.rebasePrivate(pool,t.output,WORK);throw new AssertionError();}catch(IllegalStateException expected){++checks;}
        PrivatePool initial=ContextWitnessResultTransport.privatePoolSigned(t.output,x,a,WORK),rebased=ContextWitnessResultTransport.rebasePrivateSigned(t.privateAfter,t.output,WORK);require(initial.common==t.output&&rebased.common==t.output&&has(rebased.local,"flag",false)&&has(rebased.local,"seed",true),"explicit signed variants preserve negative common and full positive private manifest");
        require(pool.common==common&&!has(pool.local,"flag",false)&&t.privateAfter.common==common,"legacy/failed and signed rebases never mutate old states");
        Snapshot signed=bind(false,"!$w seed(w,1)&&~flag(w,1);");try{ContextWitnessResultTransport.privatePoolSigned(common,x,signed,WORK);throw new AssertionError();}catch(IllegalStateException expected){++checks;}
    }
    static ConstraintTransfer pass(Snapshot x,Snapshot a,Packet input){ContextUniversalNativeRows.Result rows=ContextUniversalNativeRows.inspect(x,a,64,WORK);ContextUniversalFrozenConstraints.Result c=ContextUniversalFrozenConstraints.closeSigned(rows,input,null,16,16,512,256,WORK);ConstraintTransfer t=ContextWitnessResultTransport.transferConstraints(c,input,16,WORK);require(t.transferred,t.reason);return t;}
    static Map<Cut,ConstraintTransfer> map(ConstraintTransfer... values){Map<Cut,ConstraintTransfer> m=new LinkedHashMap<>();for(ConstraintTransfer t:values)m.put(t.target,t);return m;}
    static void barrierNo(ConstraintBarrier b,String why){require(!b.merged&&b.packet==null&&b.branches.isEmpty()&&b.privatePools.isEmpty(),why+": "+b.reason);}
    static void barriersAndFailures()throws Exception {
        Snapshot x=bind(true,"!seed(1); !@w seed(w)->p(w);"),a=bind(false,"!@w p(w)->q(w);"),b=bind(false,"!@w q(w)->r(w);");Packet input=ContextPrivateWitnessPoolRunner.common(x);ConstraintTransfer xx=pass(x,null,input),aa=pass(x,a,input),bb=pass(x,b,input);Family family=ContextWitnessResultTransport.family(input,Arrays.asList(xx.target,aa.target,bb.target),WORK);Map<Cut,ConstraintTransfer> outputs=map(xx,aa,bb);ConstraintBarrier good=ContextWitnessResultTransport.mergeConstraints(family,outputs,WORK);require(good.merged,good.reason);
        barrierNo(ContextWitnessResultTransport.mergeConstraints(family,map(aa,bb),WORK),"missing expected self-X output");barrierNo(ContextWitnessResultTransport.mergeConstraints(ContextWitnessResultTransport.family(input,Arrays.asList(aa.target,bb.target),WORK),map(aa,bb),WORK),"self-X cannot be omitted from expected list");barrierNo(ContextWitnessResultTransport.mergeConstraints(family,outputs,1),"merge work cap no prefix");
        Map<Cut,ConstraintTransfer> swapped=map(xx,aa,bb);swapped.put(aa.target,bb);swapped.put(bb.target,aa);barrierNo(ContextWitnessResultTransport.mergeConstraints(family,swapped,WORK),"swapped owning cuts");
        ConstraintTransfer failed=ContextWitnessResultTransport.transferConstraints(bb.proof,input,16,1);require(!failed.transferred,"actual failed later transfer fixture");barrierNo(ContextWitnessResultTransport.mergeConstraints(family,map(xx,aa,failed),WORK),"earlier signed outputs cannot escape after later failed transfer");
        ConstraintTransfer later=pass(x,b,good.packet);barrierNo(ContextWitnessResultTransport.mergeConstraints(family,map(xx,aa,later),WORK),"mixed common barrier objects");
        Snapshot cx=bind(true,"!p(1);"),ca=bind(false,"!~p(1);"),bad=bind(false,"!a(1)||b(1);");Packet initial=ContextPrivateWitnessPoolRunner.common(cx);Result refutedFirst=run(cx,Arrays.asList(ca,bad),initial,Collections.emptyMap(),8);incomplete(refutedFirst,"checks",0,"earlier valid refutation cannot masquerade as complete all-cut check if a later original row unsupported");
        Result direct=run(cx,Collections.singletonList(ca),initial,Collections.emptyMap(),8);refuted(direct,1,"direct collision checked before any transfers");try{direct.refutations.clear();throw new AssertionError();}catch(UnsupportedOperationException expected){++checks;}
        Snapshot anchor=bind(true,"!anchor(1);"),pa=bind(false,"!p(1);"),np=bind(false,"!~p(1);");Snapshot invalid=ContextProductionNativeBinding.trusted("own",Arrays.asList(pa,np),WORK);Result foreign=run(anchor,Collections.singletonList(invalid),ContextPrivateWitnessPoolRunner.common(anchor),Collections.emptyMap(),8);refuted(foreign,1,"foreign-only inconsistent trusted cut also refuses");require(foreign.refutations.get(Cut.of(invalid)).foreignRefuted&&!foreign.refutations.get(Cut.of(invalid)).xRefuted,"foreign-only evidence never invents X dependence");
        incomplete(run(x,Arrays.asList(a,a),input,Collections.emptyMap(),8),"preflight",0,"duplicate cuts");incomplete(ContextUniversalSignedRounds.run(x,Arrays.asList(a,b),input,Collections.emptyMap(),full(),8,1),"preflight",0,"scheduler work cap");stable(run(anchor,Collections.emptyList(),ContextPrivateWitnessPoolRunner.common(anchor),Collections.emptyMap(),1));
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("signed-rounds-").toString());originalAndMergedOpposites();stableSourcePoolsAndIndependence();privatePools();signedRebaseGuards();barriersAndFailures();System.out.println("CONTEXT_UNIVERSAL_SIGNED_ROUNDS_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
